#include "control_transport.h"
static int wr(struct xhci_controller*c,uint32_t off,uint32_t value){struct xhci_io*i=&c->io;return !(off&3)&&i->aperture>=4&&off<=i->aperture-4&&i->write32(i->ctx,off,value);}
static int rd(struct xhci_controller*c,uint32_t off,uint32_t*v){struct xhci_io*i=&c->io;return !(off&3)&&i->aperture>=4&&off<=i->aperture-4&&i->read32(i->ctx,off,v);}
static void wipe(struct xhci_ep0_dma*m){volatile uint8_t*b=m->bounce;for(unsigned i=0;i<sizeof m->bounce;i++)b[i]=0;}
int xhci_ep0_init(struct xhci_ep0*e,struct xhci_controller*c,struct xhci_ep0_dma*m,uint64_t d){if(!e||!c||c->state!=2||c->cmd.count||!m||((uintptr_t)m&63)||!d||(d&65535)||d>UINT64_MAX-sizeof(*m)||(!c->caps.ac64&&d+sizeof(*m)>0x100000000ull)||!c->cmd.dma||c->cmd.dma>UINT64_MAX-sizeof(struct xhci_dma)||(d<c->cmd.dma+sizeof(struct xhci_dma)&&c->cmd.dma<d+sizeof(*m))||c->io.aperture<8||c->caps.db>c->io.aperture-8||!(c->caps.db+8<=c->caps.rt||c->caps.db>=c->caps.rt+0x40))return 0;struct xhci_ep0 v={.controller=c,.memory=m,.bounce_dma=d+offsetof(struct xhci_ep0_dma,bounce)};if(!xhci_control_init(&v.ring,m->ring,d,1))return 0;wipe(m);*e=v;return 1;}
int xhci_ep0_transfer(void*ctx,const uint8_t s[8],uint8_t*b,size_t n,size_t*actual){struct xhci_ep0*e=ctx;if(!actual)return 0;*actual=0;if(!e||!e->controller||!e->memory||e->unusable||!s||n>sizeof e->memory->bounce||(n&&!b)||n!=((unsigned)s[6]|(unsigned)s[7]<<8))return 0;struct xhci_controller*c=e->controller;if(c->state!=2||c->cmd.count||e->ring.state)return 0;wipe(e->memory);if(!(s[0]&128))for(size_t j=0;j<n;j++)e->memory->bounce[j]=b[j];if(!xhci_control_submit(&e->ring,s,n?e->bounce_dma:0,n))return 0;__atomic_thread_fence(__ATOMIC_RELEASE);if(!wr(c,c->caps.db+4*e->ring.slot,1))goto fail;
 for(unsigned k=0;k<1000;k++){uint32_t status;if(!rd(c,c->caps.op+4,&status)||(status&((1u<<0)|(1u<<2)|(1u<<12))))goto fail;struct xhci_trb event;uint64_t next;int got=xhci_event_pop(&c->event,&event,&next);if(got<0)goto fail;if(!got){c->io.delay_ms(c->io.ctx);continue;}uint64_t erdp=next|8;if(!wr(c,c->caps.rt+0x38,(uint32_t)erdp)||!wr(c,c->caps.rt+0x3c,(uint32_t)(erdp>>32)))goto fail;if(((event.control>>10)&63)==34)continue;unsigned transferred;int done=xhci_control_event(&e->ring,&event,&transferred);if(done<0)goto fail;if(!done)continue;if(transferred>n)goto fail;__atomic_thread_fence(__ATOMIC_ACQUIRE);if(s[0]&128)for(unsigned j=0;j<transferred;j++)b[j]=e->memory->bounce[j];*actual=transferred;wipe(e->memory);return 1;}
 fail:e->unusable=1;e->ring.state=2;c->state=1;if(xhci_controller_stop(c))wipe(e->memory);return 0;
}
